constexpr void atomicCompoundAssign(Impl &impl, const U &rhs) {
    impl.atomicOperation([&rhs](auto &val) -> bool {
        if constexpr (ComparableType<std::remove_reference_t<decltype(val)>>) {
            auto oldValue = val;
            Op{}(val, rhs);
            return oldValue != val;
        } else {
            Op{}(val, rhs);
            return true;
        }
    });
}

