        } else {
            // Cache miss - collect from graph and cache the result
            if (m_observerList.contains(node)) {
                for (auto &ob : m_observerList.at(node).get()) {
                    if (auto wp = ob.lock()) [[likely]] {
                        wp->updateDepth(depth);
